create table public.risk_assessments(id uuid primary key default gen_random_uuid(),checklist_item_id uuid not null unique references public.checklist_items(id) on delete cascade,assessor_id uuid not null references public.profiles(id),frequency int not null check(frequency between 1 and 5),severity int not null check(severity between 1 and 5),risk_score int generated always as (frequency*severity) stored,level text generated always as (case when frequency*severity>=16 then 'CRITICAL' when frequency*severity>=10 then 'HIGH' when frequency*severity>=5 then 'MEDIUM' else 'LOW' end) stored,comment text,created_at timestamptz not null default now());
create table public.risk_countermeasures(id uuid primary key default gen_random_uuid(),assessment_id uuid not null references public.risk_assessments(id) on delete cascade,description text not null,due_date date,is_completed boolean not null default false,completed_at timestamptz);
alter table public.risk_assessments enable row level security;alter table public.risk_countermeasures enable row level security;
create policy "risk manager read" on public.risk_assessments for select to authenticated using((select private.is_manager()));create policy "counter manager read" on public.risk_countermeasures for select to authenticated using((select private.is_manager()));
create or replace function public.assess_risk(p_checklist_item_id uuid,p_frequency int,p_severity int,p_comment text default null) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid;begin if not private.is_manager() then raise exception 'Manager required';end if;insert into public.risk_assessments(checklist_item_id,assessor_id,frequency,severity,comment) values(p_checklist_item_id,auth.uid(),p_frequency,p_severity,p_comment) returning id into v_id;return v_id;end;$$;
revoke all on function public.assess_risk(uuid,int,int,text) from public,anon;grant execute on function public.assess_risk(uuid,int,int,text) to authenticated;grant select on public.risk_assessments,public.risk_countermeasures to authenticated;
